            s = v
            l = v
            h = v
        else:
            c += 1
            s += v
            if v < l:
                l = v
            if v > h:
                h = v

    if c == 0:
        l = 0
        h = 0

    os.makedirs("./out", exist_ok=True)
    with open("./out/stats.txt", "w") as f:
        f.write(f"{c} {s} {l} {h}\n")

